mapper.select:
SELECT * FROM task_messages
WHERE organization_id = #{organizationId} AND task_id = #{taskId}
ORDER BY created_at ASC, id ASC

mapper.insert:
INSERT INTO task_messages
  (id, organization_id, project_id, task_id, run_id, role, content, created_by)
SELECT #{id}, t.organization_id, t.project_id, t.id, #{runId}, #{role},
       #{content, typeHandler=com.kross.support.JsonbTypeHandler}, #{createdBy}
FROM tasks t WHERE t.organization_id = #{organizationId} AND t.id = #{taskId}

mapper.update:
UPDATE sources SET status = 'ready', mime_type = #{mimeType}, size_bytes = #{sizeBytes}, sha256 = #{sha256},
  blob_key = #{blobKey}, metadata = #{metadata, typeHandler=com.kross.support.JsonbTypeHandler}
WHERE organization_id = #{organizationId} AND id = #{id} AND status = 'uploading'

